package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathIllegalStateException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen3Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_StandardNormal_MeanZero_SDOne() {
        // Testing Standard Normal Distribution: Mean = 0, SD = 1
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // P(X <= 0) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(0.0), DELTA);

        // P(X <= 1.95996398454) approx 0.975
        Assert.assertEquals(0.975, dist.cumulativeProbability(1.95996398454), 1e-5);

        // P(X <= -1.95996398454) approx 0.025
        Assert.assertEquals(0.025, dist.cumulativeProbability(-1.95996398454), 1e-5);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() {
        // Mean = 10, SD = 2
        NormalDistributionImpl dist = new NormalDistributionImpl(10.0, 2.0);

        // P(X <= 10) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(10.0), DELTA);

        // P(X <= 12) is P(Z <= 1) approx 0.841344746
        Assert.assertEquals(0.841344746, dist.cumulativeProbability(12.0), 1e-8);
    }

    @Test
    public void testCumulativeProbability_ExtremeValues() {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // Large positive x -> probability approaches 1.0
        Assert.assertEquals(1.0, dist.cumulativeProbability(100.0), DELTA);

        // Large negative x -> probability approaches 0.0
        Assert.assertEquals(0.0, dist.cumulativeProbability(-100.0), DELTA);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidSD_Zero() {
        // Standard deviation must be positive. 
        // If SD is 0, the division in the formula will result in NaN or error depending on Erf implementation.
        // Most Commons Math distributions throw exception on construction or usage.
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 0.0);
        dist.cumulativeProbability(1.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidSD_Negative() {
        // Constructor usually validates SD
        new NormalDistributionImpl(0.0, -1.0);
    }

    @Test
    public void testCumulativeProbability_WithSetters() {
        NormalDistributionImpl dist = new NormalDistributionImpl();
        dist.setMean(5.0);
        dist.setStandardDeviation(1.0);

        // P(X <= 5) = 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(5.0), DELTA);

        dist.setMean(0.0);
        dist.setStandardDeviation(5.0);
        // P(X <= 0) = 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(0.0), DELTA);
    }
}
